const year = $('Phase 3 Form').first().json.Year;
const quarterRaw = $('Phase 3 Form').first().json.Quarter;
const quarter = parseInt(quarterRaw.replace('Q', ''));
const word_report_file = $('Upload Word Report').first().json.path;
const management_accounts_file = $('Upload MA').first().json.path;
const compliance_certificate_file = $('Upload Compliance').first().json.path;
const rent_roll_file = $('Upload Rent Roll').first().json.path;
const sales_tracker_file = $('Upload Sales').first().json.path;

return [{
  json: {
    year: year,
    quarter: quarter,
    word_report_file: word_report_file,
    management_accounts_file: management_accounts_file,
    compliance_certificate_file: compliance_certificate_file,
    rent_roll_file: rent_roll_file,
    sales_tracker_file: sales_tracker_file
  }
}];

